// ============================================
// DENGARKAN — Silent Audio Helper
//
// Minimal silent PCM WAV data URI used as a keep-alive buffer for mobile
// background audio sessions (iOS Safari & Android Chrome).
//
// Why this exists:
// When transitioning between tracks on a locked screen, if the audio element
// reaches 'ended' or stops outputting audio before the next track starts,
// mobile OSs (especially iOS WebKit) immediately suspend background execution
// and revoke autoplay permissions.
//
// By playing this inaudible looping audio during any network fetch gap,
// the OS audio session remains continuously active and authorized.
// ============================================

export const SILENT_AUDIO_URI =
  "data:audio/wav;base64,";

/**
 * Checks if a given URL/source is the keep-alive silent audio.
 */
export function isSilentAudioUri(src?: string | null): boolean {
  if (!src) return false;
  return src.startsWith("data:audio/wav;base64,UklGRkQDA");
}
